/** A sink that keeps its lines in memory and counts its closes. */
function memorySink(): TrajectorySink & { lines: string[]; closed: number } {
  const sink = {
    lines: [] as string[],
    closed: 0,
    write(line: string) { sink.lines.push(line) },
    close() { sink.closed += 1 },
