/**
 * Pure types of the shift driver: the frozen plan, the five `shift/*` events
 * one shift session carries, and the deployment records the config validates
 * into, free of host-side imports.
 *
 * @module @deepseek-ai/dsh-shifts/types
 */

import type { EnvironmentId, EnvironmentRunModel } from '@deepseek-ai/dsh-environments/types'
import type { FleetCell, FleetEnvironmentSelection } from '@deepseek-ai/dsh-fleet/types'
import type { SessionId } from '@deepseek-ai/dsh-session'

declare module '@deepseek-ai/dsh-session/types' {
  interface SessionEventMap {
    /**
     * Opening record of one shift: the identity the slot froze, the digest its
     * plan hashes to, the frozen plan verbatim, and the slot time the cadence
     * computed. Appended once, before the shift's first cell starts, and the
     * only event that tells a later process a shift exists to resume.
     */
    'shift/start': ShiftStart
    /**
     * One cell of the shift settled: the cell's coordinates, the session the
     * runner created for it when one exists, and its outcome. Appended once
     * per cell, after the cell's own session is durable — including for an
     * orphan a later process found stamped but unrecorded, which it records as
     * `interrupted` and never runs again.
     */
    'shift/cell': ShiftCellRecord
    /**
     * A later process picked this shift up: the cells already settled and the
     * cells this process runs. Appended after the orphans of the interrupted
     * process are recorded and before the pending cells start.
     */
    'shift/resume': ShiftResume
    /**
     * The slot was refused and no shift started: the plan digest and slot time
     * that were refused, and why. It is the only event of its session, so a
     * refused slot is as durable as a run one.
     */
    'shift/skipped': ShiftSkipped
    /**
     * Closing record of one shift: how it ended, the tokens this process's
     * cells spent, and the cell counts per outcome. Its presence is what marks
     * the shift finished, so a session with `shift/start` and no `shift/end`
     * is exactly what a later process resumes.
     */
    'shift/end': ShiftEnd
  }
}

/**
 * One shift's frozen plan. `environments` holds the ids a config filter
 * resolved to against the registry at freeze time, so the digest and the cell
 * enumeration are decided before any cell runs and a registry that changes
 * mid-shift cannot move them.
 */
export interface ShiftPlan {
  /** District every cell of the shift is stamped with. */
  readonly district: string
  /** Environments the shift runs, as resolved at freeze time. */
  readonly environments: readonly EnvironmentId[]
  /** Model routes in listing order; an empty list runs the composition's default route. */
  readonly models: readonly EnvironmentRunModel[]
  /** Positive number of repetitions per environment and route; repetition indexes start at zero. */
  readonly repetitions: number
  /** Positive integer bound on the input plus output tokens the shift's reported cells may sum to. */
  readonly tokenCeiling?: number
}

/** Payload of `shift/start`. */
export interface ShiftStart {
  /** `shift-<digest>-<scheduledAt>`, the `group` every cell of this shift is stamped with. */
  readonly shiftId: string
  /** Content digest of {@link ShiftStart.plan}. */
  readonly digest: string
  /** The frozen plan, verbatim. */
  readonly plan: ShiftPlan
  /** Slot time in epoch milliseconds; the cadence counts the next slot from it. */
  readonly scheduledAt: number
}

/**
 * What one cell of a shift produced: a report with its certification, the
 * failure that prevented one, or the crash that left a started cell with no
 * outcome at all.
 */
export type ShiftCellOutcome =
  | { readonly kind: 'reported'; readonly certified: boolean }
  | { readonly kind: 'error'; readonly code?: string; readonly message: string }
  | { readonly kind: 'interrupted' }

/** Payload of `shift/cell`. */
export interface ShiftCellRecord {
  /** The shift this cell belongs to; it equals the `shift/start` of the same session. */
  readonly shiftId: string
  /** The environment, model route, and repetition this record settles. */
  readonly cell: FleetCell
  /** Session the runner created for the cell, absent for a cell that never reached the runner. */
  readonly sessionId?: SessionId
  readonly outcome: ShiftCellOutcome
}

/** Payload of `shift/resume`. */
export interface ShiftResume {
  readonly shiftId: string
  /** Cells that will not run again: those already recorded, plus the orphans just recorded. */
  readonly done: readonly FleetCell[]
  /** Cells this process runs, in plan order. */
  readonly pending: readonly FleetCell[]
}

/** Why a slot was refused before any cell of it existed. */
export type ShiftSkipReason = 'overlap' | 'spend-window'

/** Payload of `shift/skipped`. */
export interface ShiftSkipped {
  /** Digest of the plan the refused slot would have run. */
  readonly digest: string
  /** Slot time in epoch milliseconds the cadence computed for the refused slot. */
  readonly scheduledAt: number
  readonly reason: ShiftSkipReason
}

/**
 * How a shift ended: `completed` once every pending cell settled, `ceiling`
 * when the plan's token ceiling refused the cells that were left, `stopped`
 * when disposal or {@link ShiftEnd} cancellation cut the run short.
 */
export type ShiftEndOutcome = 'completed' | 'ceiling' | 'stopped'

/** Cells of one shift counted by the outcome their `shift/cell` records carry. */
export interface ShiftCellCounts {
  readonly reported: number
  readonly error: number
  readonly interrupted: number
}

/** Payload of `shift/end`. */
export interface ShiftEnd {
  readonly shiftId: string
  readonly outcome: ShiftEndOutcome
  /** Input plus output tokens this process's cells reported; the spend window sums it across slots. */
  readonly spend: number
  /** Counts over every `shift/cell` of the session, this process's and its predecessors'. */
  readonly cells: ShiftCellCounts
}

/** Environments, routes, repetitions, and ceiling one district's slots run. */
export interface ShiftPlanConfig {
  /** Environments to run: named ids, or everything the registry filter matches at freeze time. */
  environments: FleetEnvironmentSelection
  /** Model routes; an empty list runs the composition's default route. */
  models: EnvironmentRunModel[]
  /** Positive number of repetitions per environment and route. */
  repetitions: number
  /** Positive integer token ceiling of one shift; absent runs each shift uncapped. */
  tokenCeiling?: number
}

/** How often one district opens a slot. */
export interface ShiftCadenceConfig {
  /** Positive milliseconds between consecutive slots of the district. */
  intervalMs: number
}

/** The spend a district may reach across slots before its next one is refused. */
export interface ShiftSpendWindowConfig {
  /** Positive width of the trailing window in milliseconds. */
  windowMs: number
  /** Positive token sum inside the window at which the next slot is refused. */
  maxTokens: number
}

/** One district's shifts: what they run, how often, and what they may spend. */
export interface ShiftDistrictConfig {
  /** District name, unique in the deployment; every cell's run stamp carries it. */
  district: string
  plan: ShiftPlanConfig
  cadence: ShiftCadenceConfig
  /** Cross-slot spend ceiling; absent lets the district run every slot its cadence opens. */
  spendWindow?: ShiftSpendWindowConfig
}

/**
 * Freezing one shift: the content digest computed before any cell runs, the
 * shift instance id derived from it and the slot time, and the cell
 * enumeration both the ledger and the fleet run take.
 *
 * @module @deepseek-ai/dsh-shifts/plan
 */

import { createHash } from 'node:crypto'
import type { FleetCell } from '@deepseek-ai/dsh-fleet/types'
import type { ShiftPlan } from './types.ts'

/**
 * Group namespace this package owns. A stamp `group` starting with it names a
 * shift, so no other producer may mint one.
 */
export const SHIFT_ID_PREFIX = 'shift-'

/** Self-declared version of the digested plan fields; a change to what they cover changes it. */
const SHIFT_PLAN_VERSION = 1

const SHIFT_ID_PATTERN = new RegExp(`^${SHIFT_ID_PREFIX}([0-9a-f]{64})-(0|[1-9][0-9]*)$`)

/**
 * Content digest of the fields that decide what a shift runs: the district,
 * the environment ids sorted by code unit so a registry listing order cannot
 * change the identity, the model routes in listing order because the fleet
 * enumerates cells in it, the repetition count, and the token ceiling. The
 * workspace root, the cadence, and the spend window are deployment choices and
 * stay out: they decide what a deployment pays for, not what the shift runs.
 * @param plan - the frozen plan to digest.
 * @returns the SHA-256 hex digest; identical inputs give identical digests.
 */
export function shiftDigest(plan: ShiftPlan): string {
  const content = JSON.stringify({
    version: SHIFT_PLAN_VERSION,
    district: plan.district,
    environments: [...plan.environments].sort(),
    models: plan.models.map(model => [model.provider, model.model]),
    repetitions: plan.repetitions,
    tokenCeiling: plan.tokenCeiling ?? null,
  })
  return createHash('sha256').update(content).digest('hex')
}

/**
 * Identity of one shift instance, and the stamp `group` every cell of it
 * carries. Two processes that compute the same slot compute the same identity
 * without counting anything, so a restart resumes a shift instead of minting a
 * second one.
 * @param digest - the frozen plan digest.
 * @param scheduledAt - the slot time in epoch milliseconds.
 * @returns `shift-<digest>-<scheduledAt>`.
 */
export function shiftId(digest: string, scheduledAt: number): string {
  return `${SHIFT_ID_PREFIX}${digest}-${scheduledAt}`
}

/**
 * Read an id minted by {@link shiftId}.
 * @param id - a stamp `group` or a shift session id.
 * @returns the digest and slot time, or `undefined` for an id outside this
 *   package's namespace or malformed inside it.
 */
export function parseShiftId(id: string): { digest: string; scheduledAt: number } | undefined {
  const match = SHIFT_ID_PATTERN.exec(id)
  if (match === null) return undefined
  return { digest: match[1] as string, scheduledAt: Number(match[2]) }
}

/**
 * Every cell of a frozen plan, in the order the fleet enumerates them:
 * environment-major, then model route, then repetition from zero.
 * @param plan - the frozen plan to enumerate.
 * @param defaultModel - the composition's default route, used when the plan names none.
 * @returns the cells in plan order.
 */
export function shiftCells(plan: ShiftPlan, defaultModel: FleetCell['model']): FleetCell[] {
  const models = plan.models.length === 0 ? [defaultModel] : plan.models
  const cells: FleetCell[] = []
  for (const environment of plan.environments) {
    for (const model of models) {
      for (let repetition = 0; repetition < plan.repetitions; repetition += 1) cells.push({ environment, model, repetition })
    }
  }
  return cells
}

/**
 * The slot a district opens next.
 *
 * Slots form an arithmetic sequence anchored on the district's previous
 * `shift/start`, so a restart neither drifts nor doubles a slot; slots that
 * passed while no process ran are skipped rather than caught up, and the hole
 * stays visible from the arithmetic. A district with no slot yet opens one now
 * when the deployment asked to start immediately, and one interval out
 * otherwise.
 * @param previous - the district's previous slot time, absent when it has none.
 * @param intervalMs - milliseconds between consecutive slots.
 * @param now - the current epoch milliseconds.
 * @param startImmediately - whether a district without a slot opens one now.
 * @returns the next slot time in epoch milliseconds.
 */
export function nextSlotAt(
  previous: number | undefined,
  intervalMs: number,
  now: number,
  startImmediately: boolean,
): number {
  if (previous === undefined) return startImmediately ? now : now + intervalMs
  const elapsed = now - previous
  const skipped = elapsed < 0 ? 0 : Math.floor(elapsed / intervalMs)
  return previous + (skipped + 1) * intervalMs
}

/**
 * Reading the shift ledger back out of persisted session logs: one shift's
 * `shift/*` events folded into a record, the `environment/run` stamps the
 * cells of a shift left behind, and the four questions a restarting driver
 * asks of them — which cells are still pending, what the shift already spent,
 * what the district spent inside its window, and when its previous slot was.
 *
 * The typed `SessionEventMap` decides these payloads; a malformed one is
 * rejected at append by the invariant companions that own it, so the folds
 * here read committed events rather than revalidating them.
 *
 * @module @deepseek-ai/dsh-shifts/ledger
 */

import { fleetCellKey } from '@deepseek-ai/dsh-fleet'
import type { FleetCell } from '@deepseek-ai/dsh-fleet/types'
import type { SessionEvent, SessionHeader, SessionId } from '@deepseek-ai/dsh-session'
import type { ShiftCellRecord, ShiftEnd, ShiftStart } from './types.ts'

/** One persisted session as the resume scan reads it. */
export interface ScannedSession {
  /** Stored header; `createdAt` bounds which stamps a shift may claim. */
  readonly meta: SessionHeader
  /** The stored log, oldest first. */
  readonly events: readonly SessionEvent[]
}

/** One shift session's ledger, folded from its log. */
export interface ShiftLedger {
  readonly sessionId: SessionId
  /** Header creation time; a stamped cell older than it belongs to another shift instance. */
  readonly createdAt: number
  readonly start: ShiftStart
  /** Every `shift/cell` of the session, in log order. */
  readonly cells: readonly ShiftCellRecord[]
  /** The closing record, absent while the shift is unfinished. */
  readonly end?: ShiftEnd
  /** Time of the closing record, absent while the shift is unfinished. */
  readonly endedAt?: number
}

/** One `environment/run` stamp the resume scan found, with its session's identity and spend. */
export interface StampedCell {
  /** Batch identity the stamp carries; a shift's cells carry its shift id. */
  readonly group: string
  readonly cell: FleetCell
  readonly sessionId: SessionId
  /** Header creation time of the session carrying the stamp. */
  readonly createdAt: number
  /** Input plus output tokens the session's log accounts for. */
  readonly totalTokens: number
}

/** The cells a resuming process records as orphans and the cells it runs. */
export interface ShiftPending {
  /** Cells stamped by a session of this shift that the ledger never recorded, in plan order. */
  readonly orphans: readonly FleetCell[]
  /** Cells that will not run again: recorded plus orphans, in plan order. */
  readonly done: readonly FleetCell[]
  /** Cells this process runs, in plan order. */
  readonly pending: readonly FleetCell[]
}

/**
 * Fold one persisted session into its shift ledger.
 * @param session - the stored header and log.
 * @returns the ledger, or `undefined` when the log carries no `shift/start`
 *   and is therefore not a shift session.
 */
export function foldShiftLedger(session: ScannedSession): ShiftLedger | undefined {
  let start: ShiftStart | undefined
  let end: ShiftEnd | undefined
  let endedAt: number | undefined
  const cells: ShiftCellRecord[] = []
  for (const event of session.events) {
    if (event.type === 'shift/start') start = event.data
    else if (event.type === 'shift/cell') cells.push(event.data)
    else if (event.type === 'shift/end') {
      end = event.data
      endedAt = event.time
    }
  }
  if (start === undefined) return undefined
  return {
    sessionId: session.meta.id,
    createdAt: session.meta.createdAt,
    start,
    cells,
    ...end === undefined ? {} : { end },
    ...endedAt === undefined ? {} : { endedAt },
  }
}

/**
 * The grouped `environment/run` stamps of one persisted session, each carrying
 * the tokens that session's log accounts for. A session without a grouped
 * stamp belongs to no batch and is invisible to the resume scan.
 * @param session - the stored header and log.
 * @param totalTokens - the session's folded input plus output tokens.
 * @returns one entry per grouped stamp in the log.
 */
export function stampedCells(session: ScannedSession, totalTokens: number): StampedCell[] {
  return session.events.flatMap((event) => {
    if (event.type !== 'environment/run' || event.data.group === undefined) return []
    return [{
      group: event.data.group,
      cell: {
        environment: event.data.environmentId,
        model: event.data.model,
        repetition: event.data.repetition,
      },
      sessionId: session.meta.id,
      createdAt: session.meta.createdAt,
      totalTokens,
    }]
  })
}

/**
 * Split a shift's plan cells into the orphans a resuming process records, the
 * cells that will not run again, and the cells it runs.
 *
 * A cell is done once the ledger recorded it, or once a session created at or
 * after the shift session carries its stamp — the second condition is what
 * makes the scan the authority whenever the ledger is behind, and the
 * `createdAt` bound is what keeps an older instance of the same plan out of
 * it. A stamped cell the ledger never recorded is an orphan: its session
 * exists, so running the cell again would put two sessions in one group at one
 * repetition and double-count the shift.
 * @param planCells - every cell of the frozen plan, in plan order.
 * @param ledger - the shift's folded ledger.
 * @param stamped - every grouped stamp the resume scan found.
 * @returns the orphans, the cells that will not run again, and the pending cells.
 */
export function splitPending(
  planCells: readonly FleetCell[],
  ledger: ShiftLedger,
  stamped: readonly StampedCell[],
): ShiftPending {
  const recorded = new Set(ledger.cells.map(record => fleetCellKey(record.cell)))
  const stampedKeys = new Set(stamped
    .filter(entry => entry.group === ledger.start.shiftId && entry.createdAt >= ledger.createdAt)
    .map(entry => fleetCellKey(entry.cell)))
  const orphans = planCells.filter(cell => !recorded.has(fleetCellKey(cell)) && stampedKeys.has(fleetCellKey(cell)))
  const done = planCells.filter(cell => recorded.has(fleetCellKey(cell)) || stampedKeys.has(fleetCellKey(cell)))
  const pending = planCells.filter(cell => !recorded.has(fleetCellKey(cell)) && !stampedKeys.has(fleetCellKey(cell)))
  return { orphans, done, pending }
}

/**
 * Tokens the sessions of one shift already spent.
 * @param stamped - every grouped stamp the resume scan found.
 * @param id - the shift whose sessions to sum.
 * @returns the summed input plus output tokens; `0` for a shift with no session yet.
 */
export function shiftSpend(stamped: readonly StampedCell[], id: string): number {
  return stamped
    .filter(entry => entry.group === id)
    .reduce((sum, entry) => sum + entry.totalTokens, 0)
}

/**
 * Tokens one district's finished shifts closed with inside a trailing window.
 * @param ledgers - every shift ledger the resume scan folded.
 * @param district - the district to sum.
 * @param windowMs - width of the trailing window in milliseconds.
 * @param now - the current epoch milliseconds; the window ends here.
 * @returns the summed `shift/end` spend of the district inside the window.
 */
export function windowSpend(
  ledgers: readonly ShiftLedger[],
  district: string,
  windowMs: number,
  now: number,
): number {
  return ledgers
    .filter(ledger => ledger.start.plan.district === district
      && ledger.end !== undefined
      && (ledger.endedAt as number) >= now - windowMs)
    .reduce((sum, ledger) => sum + (ledger.end as ShiftEnd).spend, 0)
}

/**
 * The latest slot one district opened.
 * @param ledgers - every shift ledger the resume scan folded.
 * @param district - the district to read.
 * @returns the slot time of the district's latest `shift/start`, or
 *   `undefined` when it has never opened one.
 */
export function previousSlot(ledgers: readonly ShiftLedger[], district: string): number | undefined {
  const slots = ledgers
    .filter(ledger => ledger.start.plan.district === district)
    .map(ledger => ledger.start.scheduledAt)
  return slots.length === 0 ? undefined : Math.max(...slots)
}

