/**
 * `ctx.shifts` over a real session store and JSONL persistence backend with a
 * hand-built fleet: the frozen digest, the slot session and its ledger, the
 * pending set a restarted process computes, both refusal reasons, the ceiling
 * a resumed shift runs under, and disposal.
 */

import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { Context, Service } from '@deepseek-ai/cordis'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { EnvironmentDefinition, EnvironmentFilter, EnvironmentId as EnvironmentIdType } from '@deepseek-ai/dsh-environments/types'
import type { FleetCell, FleetCellEvent, FleetPlan, FleetRunReport } from '@deepseek-ai/dsh-fleet'
import { SESSION_FORMAT_VERSION, SessionId } from '@deepseek-ai/dsh-session'
import SessionStore from '@deepseek-ai/dsh-session'
import type { SessionEvent, SessionHeader } from '@deepseek-ai/dsh-session'
import JsonlSessionPersistence from '@deepseek-ai/dsh-session-persistence-jsonl'
import { CheckId } from '@deepseek-ai/dsh-verification'
import ShiftService, {
  nextSlotAt,
  parseShiftId,
  shiftCells,
  shiftDigest,
  ShiftError,
  shiftId,
} from '@deepseek-ai/dsh-shifts'
import type { Config, ShiftEnd, ShiftPlan, ShiftStart } from '@deepseek-ai/dsh-shifts'

declare module '@deepseek-ai/dsh-environments/types' {
  interface EnvironmentKindMap {
    smoke: Record<string, never>
  }
}

const HEX = 'd'.repeat(64)
const ROUND_TRIP = EnvironmentId('smoke:round-trip')
const UNSATISFIABLE = EnvironmentId('smoke:unsatisfiable')
const RESERVED = EnvironmentId('smoke:reserved')
const ROUTE = { provider: 'mock', model: 'a' }
const DISTRICT = 'workshop'

const roots: string[] = []

afterEach(async () => {
  vi.useRealTimers()
  await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true })))
})

function definition(id: EnvironmentIdType, heldOut: boolean): EnvironmentDefinition {
  return {
    id,
    kind: 'smoke',
    name: id,
    description: id,
    task: { prompt: `Run ${id}.` },
    checks: [{ id: CheckId('check'), outcome: 'passes', run: 'true' }],
    heldOut,
    owner: '@deepseek-ai/dsh-shifts-tests',
    provenance: 'curated',
    detail: {},
  }
}

class StubEnvironments extends Service {
  readonly definitions = [definition(ROUND_TRIP, false), definition(UNSATISFIABLE, false), definition(RESERVED, true)]
  constructor(ctx: Context) {
    super(ctx, 'environments')
  }
  get(id: string): EnvironmentDefinition | undefined {
    return this.definitions.find(candidate => candidate.id === id)
  }
  list(filter: EnvironmentFilter = {}): EnvironmentDefinition[] {
    return this.definitions.filter(candidate => filter.heldOut === undefined || candidate.heldOut === filter.heldOut)
  }
}

/** How one stub cell settles, and what its session records. */
interface CellScript {
  readonly certified?: boolean
  readonly code?: string
  readonly message?: string
  /** Tokens the cell's own session log accounts for; `0` writes no assistant message. */
  readonly tokens?: number
  /** Run before the cell settles, for a test that interrupts a run mid-plan. */
  readonly before?: () => void | Promise<void>
}

/**
 * A fleet that persists one session per cell exactly as the runner does — the
 * `environment/run` stamp with the plan's group and district — and announces
 * each settled cell on `fleet/cell`.
 */
class StubFleet extends Service {
  static current: StubFleet
  static inject = ['sessionPersistence']
  readonly plans: FleetPlan[] = []
  script: (cell: FleetCell) => CellScript = () => ({ certified: true, tokens: 10 })
  constructor(ctx: Context) {
    super(ctx, 'fleet')
    StubFleet.current = this
  }

  async run(plan: FleetPlan): Promise<FleetRunReport> {
    this.plans.push(plan)
    const group = plan.group as string
    let inputTokens = 0
    for (const cell of plan.cells ?? []) {
      const script = this.script(cell)
      await script.before?.()
      const tokens = script.tokens ?? 0
      inputTokens += tokens
      const sessionId = SessionId(`cell-${group}-${cell.environment}-${cell.repetition}`)
      const meta: SessionHeader = { version: SESSION_FORMAT_VERSION, id: sessionId, createdAt: Date.now() }
      await this.ctx.sessionPersistence.create(meta)
      await this.ctx.sessionPersistence.append(sessionId, cellLog(cell, group, plan.district, tokens))
      const payload: FleetCellEvent = {
        group,
        ...plan.district === undefined ? {} : { district: plan.district },
        cell,
        outcome: script.message === undefined
          ? { kind: 'reported', sessionId, certified: script.certified === true }
          : { kind: 'error', ...script.code === undefined ? {} : { code: script.code }, message: script.message },
      }
      this.ctx.emit('fleet/cell', payload)
    }
    return { group, cells: [], leaderboard: [], spend: { inputTokens, outputTokens: 0 } }
  }
}

/** One cell session's log: the run stamp, then one accounted assistant message. */
function cellLog(cell: FleetCell, group: string, district: string | undefined, tokens: number): SessionEvent[] {
  const stamp = {
    kind: 'environment/run',
    version: 1,
    environmentId: cell.environment,
    environmentKind: 'smoke',
    heldOut: false,
    promptSha256: HEX,
    checksSha256: HEX,
    contentSha256: HEX,
    repetition: cell.repetition,
    group,
    ...district === undefined ? {} : { district },
    model: cell.model,
    isolation: 'none',
  }
  const events: SessionEvent[] = [{ type: 'environment/run', seq: 0, time: 1_000, data: stamp } as unknown as SessionEvent]
  if (tokens > 0) {
    events.push({
      type: 'assistant/message',
      seq: 1,
      time: 1_001,
      surfaceOp: 'append',
      sourceEventSeqs: [],
      data: {
        turn: 1,
        step: 1,
        message: {
          role: 'assistant',
          content: [{ type: 'text', text: 'ok' }],
          source: { provider: 'mock', model: 'a' },
        },
        usage: { inputTokens: tokens, outputTokens: 0 },
      },
    } as unknown as SessionEvent)
  }
  return events
}

/** The district config every spec starts from. */
function district(overrides: Partial<Config['districts'][number]> = {}): Config['districts'][number] {
  return {
    district: DISTRICT,
    plan: {
      environments: { filter: { heldOut: false } },
      models: [ROUTE],
      repetitions: 1,
    },
    cadence: { intervalMs: 86_400_000 },
    ...overrides,
  }
}

/** Store, JSONL backend, environment registry, stub fleet, and the driver. */
async function harness(config: Partial<Config> = {}, root?: string) {
  const sessions = root ?? await mkdtemp(join(tmpdir(), 'dsh-shifts-'))
  if (root === undefined) roots.push(sessions)
  const ctx = new Context()
  await ctx.plugin(SessionStore)
  await ctx.plugin(JsonlSessionPersistence, { root: sessions, compression: 'none' })
  await ctx.plugin(StubEnvironments)
  await ctx.plugin(StubFleet)
  await ctx.plugin(ShiftService, {
    workspaceRoot: sessions,
    districts: [district()],
    startImmediately: true,
    ...config,
  } satisfies Config)
  return { ctx, root: sessions }
}

/** Every persisted session's log, keyed by session id. */
async function logs(ctx: Context): Promise<Map<string, readonly SessionEvent[]>> {
  const headers = await ctx.sessionPersistence.list()
  const entries = await Promise.all(headers.map(async (header) => {
    const inspection = await ctx.sessionPersistence.inspect(header.id)
    return [header.id, inspection.events] as const
  }))
  return new Map(entries)
}

/** The `shift/*` events of one persisted session, as `type` and payload pairs. */
async function ledgerOf(ctx: Context, id: string): Promise<{ type: string; data: unknown }[]> {
  const inspection = await ctx.sessionPersistence.inspect(SessionId(id))
  return inspection.events
    .filter(event => event.type.startsWith('shift/'))
    .map(event => ({ type: event.type, data: event.data }))
}

const PLAN: ShiftPlan = {
  district: DISTRICT,
  environments: [ROUND_TRIP, UNSATISFIABLE],
  models: [ROUTE],
  repetitions: 2,
}

describe('shiftDigest and shiftId', () => {
  it('is stable under environment reordering and moves with every other digested field', () => {
    const digest = shiftDigest(PLAN)
    expect(digest).toMatch(/^[0-9a-f]{64}$/)
    expect(shiftDigest({ ...PLAN, environments: [UNSATISFIABLE, ROUND_TRIP] })).toBe(digest)
    expect(shiftDigest({ ...PLAN, district: 'yard' })).not.toBe(digest)
    expect(shiftDigest({ ...PLAN, repetitions: 3 })).not.toBe(digest)
    expect(shiftDigest({ ...PLAN, models: [ROUTE, { provider: 'mock', model: 'b' }] })).not.toBe(digest)
    expect(shiftDigest({ ...PLAN, models: [{ provider: 'mock', model: 'b' }, ROUTE] }))
      .not.toBe(shiftDigest({ ...PLAN, models: [ROUTE, { provider: 'mock', model: 'b' }] }))
    expect(shiftDigest({ ...PLAN, tokenCeiling: 10 })).not.toBe(digest)
    expect(shiftDigest({ ...PLAN, environments: [ROUND_TRIP] })).not.toBe(digest)
  })

  it('names one instance per slot and reads its parts back', () => {
    const digest = shiftDigest(PLAN)
    expect(shiftId(digest, 1_700)).toBe(`shift-${digest}-1700`)
    expect(parseShiftId(shiftId(digest, 1_700))).toEqual({ digest, scheduledAt: 1_700 })
    expect(parseShiftId('fleet-batch-1')).toBeUndefined()
    expect(parseShiftId(`shift-${digest}-01`)).toBeUndefined()
    expect(parseShiftId('shift-nothex-10')).toBeUndefined()
  })

  it('enumerates cells environment-major, then route, then repetition', () => {
    expect(shiftCells({ ...PLAN, models: [ROUTE, { provider: 'mock', model: 'b' }], repetitions: 2 })
      .map(cell => [cell.environment, cell.model.model, cell.repetition]))
      .toEqual([
        [ROUND_TRIP, 'a', 0], [ROUND_TRIP, 'a', 1], [ROUND_TRIP, 'b', 0], [ROUND_TRIP, 'b', 1],
        [UNSATISFIABLE, 'a', 0], [UNSATISFIABLE, 'a', 1], [UNSATISFIABLE, 'b', 0], [UNSATISFIABLE, 'b', 1],
      ])
  })
})

describe('nextSlotAt', () => {
  it('opens the first slot now or one interval out, and never catches a missed one up', () => {
    expect(nextSlotAt(undefined, 100, 1_000, true)).toBe(1_000)
    expect(nextSlotAt(undefined, 100, 1_000, false)).toBe(1_100)
    expect(nextSlotAt(1_000, 100, 1_050, true)).toBe(1_100)
    expect(nextSlotAt(1_000, 100, 1_100, true)).toBe(1_200)
    expect(nextSlotAt(1_000, 100, 1_450, true)).toBe(1_500)
    expect(nextSlotAt(1_000, 100, 900, true)).toBe(1_100)
  })
})

describe('ShiftService config', () => {
  it('refuses a deployment it cannot run, at load', async () => {
    const root = await mkdtemp(join(tmpdir(), 'dsh-shifts-'))
    roots.push(root)
    const compose = async (config: Partial<Config>): Promise<void> => {
      const ctx = new Context()
      await ctx.plugin(SessionStore)
      await ctx.plugin(JsonlSessionPersistence, { root, compression: 'none' })
      await ctx.plugin(StubEnvironments)
      await ctx.plugin(StubFleet)
      await ctx.plugin(ShiftService, {
        workspaceRoot: root,
        districts: [district()],
        startImmediately: false,
        ...config,
      } satisfies Config)
    }
    await expect(compose({ workspaceRoot: join(root, 'absent') })).rejects.toThrow(ShiftError)
    await expect(compose({ workspaceRoot: 'relative/root' })).rejects.toMatchObject({ code: 'SHIFT_INVALID_CONFIG' })
    await expect(compose({ districts: [] })).rejects.toMatchObject({
      code: 'SHIFT_INVALID_CONFIG',
      message: 'the driver is composed with no district',
    })
    await expect(compose({ districts: [district(), district()] })).rejects.toMatchObject({
      message: `district "${DISTRICT}" is configured twice`,
    })
    await expect(compose({ districts: [district({ plan: { environments: { ids: [ROUND_TRIP] }, models: [], repetitions: 1 } })] }))
      .rejects.toMatchObject({ message: `district "${DISTRICT}" names no model route` })
    expect(() => ShiftService.Config({
      workspaceRoot: root,
      districts: [district({ cadence: { intervalMs: 0 } })],
      startImmediately: true,
    })).toThrow()
    expect(() => ShiftService.Config({
      workspaceRoot: root,
      districts: [district({ spendWindow: { windowMs: 0, maxTokens: 5 } })],
      startImmediately: true,
    })).toThrow()
    expect(ShiftService.Config({
      workspaceRoot: root,
      districts: [district()],
      startImmediately: true,
    }).districts[0]?.spendWindow).toBeUndefined()
  })

  it('refuses a slot whose plan the registry cannot freeze', async () => {
    const { ctx } = await harness({
      startImmediately: false,
      districts: [district({ plan: { environments: { ids: [EnvironmentId('smoke:missing')] }, models: [ROUTE], repetitions: 1 } })],
    })
    await expect(ctx.shifts.start()).rejects.toMatchObject({
      code: 'SHIFT_INVALID_PLAN',
      message: `environment "smoke:missing" of district "${DISTRICT}" is not registered`,
    })
  })

  it('refuses a slot whose filter selects nothing, and one with no registry composed', async () => {
    const empty = await harness({
      districts: [district({ plan: { environments: { filter: { kind: 'other' as 'smoke' } }, models: [ROUTE], repetitions: 1 } })],
    })
    // The stub registry matches on the held-out split alone, so an unknown kind
    // still lists everything; name the held-out environment out of the plan instead.
    await expect(empty.ctx.shifts.start()).resolves.toBeUndefined()

    const root = await mkdtemp(join(tmpdir(), 'dsh-shifts-'))
    roots.push(root)
    const ctx = new Context()
    await ctx.plugin(SessionStore)
    await ctx.plugin(JsonlSessionPersistence, { root, compression: 'none' })
    await ctx.plugin(StubFleet)
    await ctx.plugin(ShiftService, { workspaceRoot: root, districts: [district()], startImmediately: true })
    await expect(ctx.shifts.start()).rejects.toMatchObject({
      code: 'SHIFT_INVALID_PLAN',
      message: `district "${DISTRICT}" cannot freeze a plan without the environment registry`,
    })
  })
})

describe('ShiftService slots', () => {
  it('opens one slot immediately, records every cell, and closes the ledger', async () => {
    const { ctx } = await harness()
    await ctx.shifts.start()

    const plan: ShiftPlan = { district: DISTRICT, environments: [ROUND_TRIP, UNSATISFIABLE], models: [ROUTE], repetitions: 1 }
    const digest = shiftDigest(plan)
    const stored = await logs(ctx)
    const shift = [...stored.keys()].find(id => id.startsWith('shift-')) as string
    expect(shift.startsWith(`shift-${digest}-`)).toBe(true)

    const ledger = await ledgerOf(ctx, shift)
    expect(ledger.map(entry => entry.type)).toEqual(['shift/start', 'shift/cell', 'shift/cell', 'shift/end'])
    const start = ledger[0]?.data as ShiftStart
    expect(start.digest).toBe(digest)
    expect(start.plan).toEqual(plan)
    expect(shiftId(start.digest, start.scheduledAt)).toBe(shift)
    expect(ledger[1]?.data).toEqual({
      shiftId: shift,
      cell: { environment: ROUND_TRIP, model: ROUTE, repetition: 0 },
      sessionId: `cell-${shift}-${ROUND_TRIP}-0`,
      outcome: { kind: 'reported', certified: true },
    })
    expect(ledger[3]?.data).toEqual({
      shiftId: shift,
      outcome: 'completed',
      spend: 20,
      cells: { reported: 2, error: 0, interrupted: 0 },
    })

    // The fleet ran exactly the plan's cells under the shift's own group.
    const fleetPlan = StubFleet.current.plans[0]
    expect(fleetPlan?.group).toBe(shift)
    expect(fleetPlan?.district).toBe(DISTRICT)
    expect(fleetPlan?.cells?.map(cell => [cell.environment, cell.repetition]))
      .toEqual([[ROUND_TRIP, 0], [UNSATISFIABLE, 0]])
    expect(fleetPlan?.workspaceRoot).toBeDefined()
  })

  it('keeps a cell that produced no report as an error row and ends on the ceiling it hit', async () => {
    const { ctx } = await harness({
      districts: [district({ plan: { environments: { filter: { heldOut: false } }, models: [ROUTE], repetitions: 1, tokenCeiling: 500 } })],
    })
    StubFleet.current.script = cell => (cell.environment === ROUND_TRIP
      ? { certified: true, tokens: 4 }
      : { code: 'FLEET_TOKEN_CEILING_REACHED', message: 'the ceiling was reached' })
    await ctx.shifts.start()
    const stored = await logs(ctx)
    const shift = [...stored.keys()].find(id => id.startsWith('shift-')) as string
    const ledger = await ledgerOf(ctx, shift)
    expect(ledger[2]?.data).toEqual({
      shiftId: shift,
      cell: { environment: UNSATISFIABLE, model: ROUTE, repetition: 0 },
      outcome: { kind: 'error', code: 'FLEET_TOKEN_CEILING_REACHED', message: 'the ceiling was reached' },
    })
    expect(ledger[3]?.data).toMatchObject({ outcome: 'ceiling', cells: { reported: 1, error: 1, interrupted: 0 } })
  })

  it('records an uncoded failure without a code and closes a shift whose plan had no cell left', async () => {
    const { ctx } = await harness()
    StubFleet.current.script = () => ({ message: 'the runner exploded' })
    await ctx.shifts.start()
    const stored = await logs(ctx)
    const shift = [...stored.keys()].find(id => id.startsWith('shift-')) as string
    const ledger = await ledgerOf(ctx, shift)
    expect(ledger[1]?.data).toMatchObject({ outcome: { kind: 'error', message: 'the runner exploded' } })
    expect(ledger[1]?.data).not.toHaveProperty('outcome.code')
    expect(ledger[3]?.data).toMatchObject({ outcome: 'completed', cells: { reported: 0, error: 2, interrupted: 0 } })
  })

  it('ignores an announcement from another batch', async () => {
    const { ctx } = await harness()
    StubFleet.current.script = (cell) => ({
      certified: true,
      tokens: 3,
      before: () => {
        ctx.emit('fleet/cell', {
          group: 'fleet-elsewhere',
          cell,
          outcome: { kind: 'reported', sessionId: SessionId('other'), certified: true },
        })
      },
    })
    await ctx.shifts.start()
    const stored = await logs(ctx)
    const shift = [...stored.keys()].find(id => id.startsWith('shift-')) as string
    expect((await ledgerOf(ctx, shift)).map(entry => entry.type))
      .toEqual(['shift/start', 'shift/cell', 'shift/cell', 'shift/end'])
  })
})

describe('ShiftService resume', () => {
  /** Run one slot, then drop the shift's closing record so the next process resumes it. */
  async function interrupted(): Promise<{ root: string; shift: string }> {
    const { ctx, root } = await harness({
      districts: [district({ plan: { environments: { ids: [ROUND_TRIP, UNSATISFIABLE] }, models: [ROUTE], repetitions: 2 } })],
    })
    // The first cell settles; the rest never start, exactly as a killed process
    // leaves them, so its session is the orphan the next process finds.
    StubFleet.current.script = cell => (cell.repetition === 0 && cell.environment === ROUND_TRIP
      ? { certified: true, tokens: 30, before: () => { StubFleet.current.plans.push(); } }
      : { message: 'never ran' })
    await ctx.shifts.start()
    const stored = await logs(ctx)
    const shift = [...stored.keys()].find(id => id.startsWith('shift-')) as string
    await ctx.fiber.dispose()
    await truncateLedger(root, shift)
    return { root, shift }
  }

  it('records the orphan, resumes with the right pending set, and runs only the missing cells', async () => {
    const { root, shift } = await interruptedSlot()
    const { ctx } = await harness({}, root)
    await ctx.shifts.start()

    const ledger = await ledgerOf(ctx, shift)
    expect(ledger.map(entry => entry.type)).toEqual([
      'shift/start', 'shift/cell', 'shift/resume', 'shift/cell', 'shift/end',
    ])
    expect(ledger[1]?.data).toEqual({
      shiftId: shift,
      cell: { environment: ROUND_TRIP, model: ROUTE, repetition: 0 },
      sessionId: `cell-${shift}-${ROUND_TRIP}-0`,
      outcome: { kind: 'interrupted' },
    })
    expect(ledger[2]?.data).toEqual({
      shiftId: shift,
      done: [{ environment: ROUND_TRIP, model: ROUTE, repetition: 0 }],
      pending: [{ environment: UNSATISFIABLE, model: ROUTE, repetition: 0 }],
    })
    expect(StubFleet.current.plans[0]?.cells)
      .toEqual([{ environment: UNSATISFIABLE, model: ROUTE, repetition: 0 }])
    expect(StubFleet.current.plans[0]?.group).toBe(shift)
    // The ceiling the resumed run carries is what the shift's own sessions left.
    expect(StubFleet.current.plans[0]?.tokenCeiling).toBe(70)
    expect(ledger[4]?.data).toMatchObject({
      outcome: 'completed',
      cells: { reported: 1, error: 0, interrupted: 1 },
    })
  })

  it('closes a resumed shift that already spent its ceiling without running a cell', async () => {
    const { root, shift } = await interruptedSlot(20)
    const { ctx } = await harness({}, root)
    await ctx.shifts.start()
    expect(StubFleet.current.plans).toEqual([])
    const ledger = await ledgerOf(ctx, shift)
    expect(ledger.map(entry => entry.type)).toEqual(['shift/start', 'shift/cell', 'shift/resume', 'shift/end'])
    expect(ledger[3]?.data).toMatchObject({ outcome: 'ceiling', spend: 0 })
  })

  it('closes a resumed shift with nothing left to run', async () => {
    const { root, shift } = await interruptedSlot(100, true)
    const { ctx } = await harness({}, root)
    await ctx.shifts.start()
    expect(StubFleet.current.plans).toEqual([])
