/** Stub session logs the shift specs fold: the ledger events and the run stamps a shift's cells leave behind. */

import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { FleetCell } from '@deepseek-ai/dsh-fleet/types'
import { SESSION_FORMAT_VERSION, SessionId } from '@deepseek-ai/dsh-session'
import type { SessionEvent, SessionHeader } from '@deepseek-ai/dsh-session'
import type { ShiftPlan } from '@deepseek-ai/dsh-shifts'

const HEX = 'd'.repeat(64)

/** Training-eligible smoke environments the specs plan over. */
export const ROUND_TRIP = EnvironmentId('smoke:round-trip')
/** The second training-eligible environment, used to make a plan of more than one cell. */
export const UNSATISFIABLE = EnvironmentId('smoke:unsatisfiable')
/** The held-out environment a `heldOut: false` filter must leave out. */
export const RESERVED = EnvironmentId('smoke:reserved')
/** The single model route the specs run. */
export const ROUTE = { provider: 'mock', model: 'a' }
/** The district every spec plans under. */
export const DISTRICT = 'workshop'

/**
 * One cell of the specs' plans.
 * @param environment - the environment the cell runs.
 * @param repetition - the zero-based repetition index.
 * @returns the cell on the specs' single route.
 */
export function cell(environment: string, repetition = 0): FleetCell {
  return { environment: EnvironmentId(environment), model: ROUTE, repetition }
}

/**
 * The stored header of one session.
 * @param id - the session identity.
 * @param createdAt - epoch milliseconds the header records.
 * @returns the header a backend stores.
 */
export function header(id: string, createdAt: number): SessionHeader {
  return { version: SESSION_FORMAT_VERSION, id: SessionId(id), createdAt }
}

/** Append-only event builder over a contiguous seq counter. */
export class Log {
  readonly events: SessionEvent[] = []

  /**
   * Push one event past the typed event map, so a spec can write a payload the
   * live API would refuse.
   * @param type - session event type.
   * @param data - the durable payload.
   * @param time - epoch milliseconds of the event.
   * @returns this builder.
   */
  push(type: string, data: unknown, time = 1_000 + this.events.length): this {
    this.events.push({ type, seq: this.events.length, time, data } as unknown as SessionEvent)
    return this
  }
}

/**
 * One cell session's log: the grouped run stamp, then one accounted assistant
 * message when the cell spent anything.
 * @param target - the cell the session ran.
 * @param group - the batch identity the stamp carries.
 * @param district - the district the stamp carries, absent for an undistricted run.
 * @param tokens - input tokens the single assistant message accounts for; `0` writes none.
 * @returns the contiguous events of that session.
 */
export function cellLog(target: FleetCell, group: string, district: string | undefined, tokens: number): SessionEvent[] {
  const log = new Log().push('environment/run', {
    kind: 'environment/run',
    version: 1,
    environmentId: target.environment,
    environmentKind: 'smoke',
    heldOut: false,
    promptSha256: HEX,
    checksSha256: HEX,
    contentSha256: HEX,
    repetition: target.repetition,
    group,
    ...district === undefined ? {} : { district },
    model: target.model,
    isolation: 'none',
  })
  if (tokens > 0) {
    log.events.push({
      type: 'assistant/message',
      seq: 1,
      time: 1_001,
      surfaceOp: 'append',
      sourceEventSeqs: [],
      data: {
        turn: 1,
        step: 1,
        message: { role: 'assistant', content: [{ type: 'text', text: 'ok' }], source: { provider: 'mock', model: 'a' } },
        usage: { inputTokens: tokens, outputTokens: 0 },
      },
    } as unknown as SessionEvent)
  }
  return log.events
}

/**
 * The plan the specs freeze, over the two training-eligible environments.
 * @param overrides - fields replacing the defaults.
 * @returns the frozen plan.
 */
export function plan(overrides: Partial<ShiftPlan> = {}): ShiftPlan {
  return {
    district: DISTRICT,
    environments: [ROUND_TRIP, UNSATISFIABLE],
    models: [ROUTE],
    repetitions: 1,
    ...overrides,
  }
}

/**
 * Freezing a shift: what the digest covers and what it deliberately ignores,
 * the instance id it names, the cell order the ledger and the fleet share, and
 * the slot arithmetic the cadence reads out of the ledger.
 */

import { describe, expect, it } from 'vitest'
import { nextSlotAt, parseShiftId, SHIFT_ID_PREFIX, shiftCells, shiftDigest, shiftId } from '@deepseek-ai/dsh-shifts'
import { DISTRICT, plan, ROUND_TRIP, ROUTE, UNSATISFIABLE } from './log.ts'

const ROUTE_B = { provider: 'mock', model: 'b' }

describe('shiftDigest', () => {
  it('is stable under environment reordering and moves with every other digested field', () => {
    const digest = shiftDigest(plan())
    expect(digest).toMatch(/^[0-9a-f]{64}$/)
    expect(shiftDigest(plan({ environments: [UNSATISFIABLE, ROUND_TRIP] }))).toBe(digest)
    expect(shiftDigest(plan({ environments: [ROUND_TRIP] }))).not.toBe(digest)
    expect(shiftDigest(plan({ district: 'yard' }))).not.toBe(digest)
    expect(shiftDigest(plan({ repetitions: 2 }))).not.toBe(digest)
    expect(shiftDigest(plan({ models: [ROUTE, ROUTE_B] }))).not.toBe(digest)
    expect(shiftDigest(plan({ tokenCeiling: 10 }))).not.toBe(digest)
    expect(shiftDigest(plan({ tokenCeiling: 11 }))).not.toBe(shiftDigest(plan({ tokenCeiling: 10 })))
  })

  it('keeps the routes in listing order, because the cells run in it', () => {
    expect(shiftDigest(plan({ models: [ROUTE, ROUTE_B] })))
      .not.toBe(shiftDigest(plan({ models: [ROUTE_B, ROUTE] })))
  })
})

describe('shiftId', () => {
  it('names one instance per slot and reads its parts back', () => {
    const digest = shiftDigest(plan())
    expect(shiftId(digest, 1_700)).toBe(`${SHIFT_ID_PREFIX}${digest}-1700`)
    expect(parseShiftId(shiftId(digest, 1_700))).toEqual({ digest, scheduledAt: 1_700 })
    expect(parseShiftId(shiftId(digest, 0))).toEqual({ digest, scheduledAt: 0 })
    expect(parseShiftId('fleet-batch-1')).toBeUndefined()
    expect(parseShiftId(`${SHIFT_ID_PREFIX}${digest}-01`)).toBeUndefined()
    expect(parseShiftId(`${SHIFT_ID_PREFIX}not-hex-10`)).toBeUndefined()
  })
})

describe('shiftCells', () => {
  it('enumerates environment-major, then route, then repetition from zero', () => {
    expect(shiftCells(plan({ models: [ROUTE, ROUTE_B], repetitions: 2 }))
      .map(cell => [cell.environment, cell.model.model, cell.repetition]))
      .toEqual([
        [ROUND_TRIP, 'a', 0], [ROUND_TRIP, 'a', 1], [ROUND_TRIP, 'b', 0], [ROUND_TRIP, 'b', 1],
        [UNSATISFIABLE, 'a', 0], [UNSATISFIABLE, 'a', 1], [UNSATISFIABLE, 'b', 0], [UNSATISFIABLE, 'b', 1],
      ])
    expect(shiftCells(plan()).every(cell => cell.model === ROUTE)).toBe(true)
    expect(plan().district).toBe(DISTRICT)
  })
})

describe('nextSlotAt', () => {
  it('opens the first slot now or one interval out, and never catches a missed one up', () => {
    expect(nextSlotAt(undefined, 100, 1_000, true)).toBe(1_000)
    expect(nextSlotAt(undefined, 100, 1_000, false)).toBe(1_100)
    expect(nextSlotAt(1_000, 100, 1_050, true)).toBe(1_100)
    expect(nextSlotAt(1_000, 100, 1_100, true)).toBe(1_200)
    // Slots that passed while no process ran leave the hole visible in the arithmetic.
    expect(nextSlotAt(1_000, 100, 1_450, true)).toBe(1_500)
    // A clock that jumped backwards moves a slot and never doubles one.
    expect(nextSlotAt(1_000, 100, 900, true)).toBe(1_100)
  })
})

/**
 * Reading the ledger back: what makes a persisted session a shift session, the
 * pending set a restarting process computes from records and run stamps, and
 * the three sums the cadence and the spend window read.
