      { group: ID, cell: cell(UNSATISFIABLE), sessionId: SessionId('b'), createdAt: 700, totalTokens: 12 },
      { group: 'fleet-elsewhere', cell: cell(ROUND_TRIP), sessionId: SessionId('c'), createdAt: 800, totalTokens: 99 },
