/**
 * The package companion's owned relations over the shift ledger: a record that
 * follows the `shift/start` of its own shift, one record per cell, and a
 * `shift/start` whose plan freezes to the digest it declares. Seeded sessions
 * exercise the startup scan and live appends the pre-publication check.
 */

import { describe, expect, it } from 'vitest'
import { Context } from '@deepseek-ai/cordis'
import InvariantRegistry, { InvariantError } from '@deepseek-ai/dsh-invariants'
import SessionStore, { SessionId } from '@deepseek-ai/dsh-session'
import type { Session, SessionEvent } from '@deepseek-ai/dsh-session'
import { shiftDigest, shiftId } from '@deepseek-ai/dsh-shifts'
import * as ShiftInvariantCompanion from '@deepseek-ai/dsh-shifts/invariant'
import { cell, plan, ROUND_TRIP, UNSATISFIABLE } from './log.ts'

const PACKAGE_NAME = '@deepseek-ai/dsh-shifts'
const PLAN = plan()
const DIGEST = shiftDigest(PLAN)
const ID = shiftId(DIGEST, 1_000)

/** One durable payload as the log carries it, before the typed map narrows it. */
type Raw = Record<string, unknown>

/** Append one durable payload the typed session API would not accept verbatim. */
function append(session: Session, type: string, data: Raw): void {
  ;(session.append as unknown as (eventType: string, eventData: unknown) => unknown)(type, data)
}

/** The opening record of the specs' shift, with the fields under test overridable. */
function start(overrides: Raw = {}): Raw {
  return { shiftId: ID, digest: DIGEST, plan: PLAN, scheduledAt: 1_000, ...overrides }
}

/** One settled cell record. */
function record(environment: string, overrides: Raw = {}): Raw {
  return { shiftId: ID, cell: cell(environment), outcome: { kind: 'reported', certified: true }, ...overrides }
}

/** Mount the store plus the companion, optionally over an already-seeded session. */
async function setup(seed?: readonly SessionEvent[]): Promise<Context> {
  const ctx = new Context()
  await ctx.plugin(SessionStore)
  if (seed !== undefined) ctx.sessions.create(SessionId('shifts-seeded'), { seed })
  await ctx.plugin(InvariantRegistry, { enabled: true })
  await ctx.plugin(ShiftInvariantCompanion)
  return ctx
}

/** A seeded log of the given durable payloads, in order. */
function seeded(...events: readonly [string, Raw][]): SessionEvent[] {
  return events.map(([type, data], seq) => ({ type, seq, time: 1_000 + seq, data } as unknown as SessionEvent))
}

describe('shift ledger invariants', () => {
  it('accepts a complete ledger and leaves every other event alone', async () => {
    await expect(setup(seeded(
      ['shift/start', start()],
      ['shift/cell', record(ROUND_TRIP)],
      ['shift/cell', record(UNSATISFIABLE)],
      ['shift/resume', { shiftId: ID, done: [], pending: [] }],
      ['shift/end', { shiftId: ID, outcome: 'completed', spend: 3, cells: { reported: 2, error: 0, interrupted: 0 } }],
    ))).resolves.toBeDefined()

    const ctx = await setup()
    const session = ctx.sessions.create(SessionId('shifts-other'))
    expect(() => {
      session.append('turn/start', { turn: 1 })
      session.append('turn/end', { turn: 1, reason: { kind: 'completed' } })
    }).not.toThrow()
    expect(session.seq).toBe(2)
  })

  it('rejects a record that no `shift/start` of this session opened', async () => {
    const ctx = await setup()
    const session = ctx.sessions.create(SessionId('shifts-unopened'))
    expect(() => {
      append(session, 'shift/cell', record(ROUND_TRIP))
    }).toThrow(expect.objectContaining<Partial<InvariantError>>({ code: 'INVARIANT', packageName: PACKAGE_NAME }))
    expect(session.seq).toBe(0)

    await expect(setup(seeded(['shift/end', { shiftId: ID, outcome: 'completed', spend: 0, cells: { reported: 0, error: 0, interrupted: 0 } }])))
      .rejects.toThrow(InvariantError)
    await expect(setup(seeded(['shift/resume', { shiftId: ID, done: [], pending: [] }])))
      .rejects.toThrow(InvariantError)
  })

  it('rejects a record naming another shift than the one this session started', async () => {
    const ctx = await setup(seeded(['shift/start', start()]))
    const session = ctx.sessions.get(SessionId('shifts-seeded')) as Session
    expect(() => {
      append(session, 'shift/cell', record(ROUND_TRIP, { shiftId: shiftId(DIGEST, 2_000) }))
    }).toThrow(InvariantError)
  })

  it('rejects a second record for one cell of one shift', async () => {
    const ctx = await setup(seeded(['shift/start', start()], ['shift/cell', record(ROUND_TRIP)]))
    const session = ctx.sessions.get(SessionId('shifts-seeded')) as Session
    expect(() => {
      append(session, 'shift/cell', record(ROUND_TRIP, { outcome: { kind: 'interrupted' } }))
    }).toThrow(InvariantError)
    expect(() => {
      append(session, 'shift/cell', record(UNSATISFIABLE))
    }).not.toThrow()
  })

  it('rejects a `shift/start` whose plan freezes to another digest', async () => {
    const ctx = await setup()
    const session = ctx.sessions.create(SessionId('shifts-unfrozen'))
    expect(() => {
      append(session, 'shift/start', start({ digest: 'a'.repeat(64) }))
    }).toThrow(expect.objectContaining<Partial<InvariantError>>({ code: 'INVARIANT', packageName: PACKAGE_NAME }))
    expect(() => {
      append(session, 'shift/start', start({ plan: { ...PLAN, repetitions: 9 } }))
    }).toThrow(InvariantError)
    expect(session.seq).toBe(0)
  })
})

#!/usr/bin/env node
/**
 * Test driver: boot the shift-driver composition, run the district's due slot
 * to completion, and print every shift ledger plus the run stamps the cells
 * left in the persistence root.
 *
 * With `DSH_TEST_SHIFT_KILL_AFTER_CELL` set, the driver instead stays up like
 * an unattended process and exits hard on the first announced cell, leaving a
 * shift whose ledger is open and whose first cell has a session but no record —
 * exactly the state the next boot resumes.
 */

import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-fleet'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import type { SessionPersistence } from '@deepseek-ai/dsh-session-persistence'
import type {} from '@deepseek-ai/dsh-shifts'

/** Exit code the kill switch leaves behind, distinct from every clean exit. */
const KILLED = 9

/** One shift session's ledger as the e2e asserts on it. */
interface LedgerLine {
  readonly sessionId: string
  readonly events: { readonly type: string; readonly data: unknown }[]
}

/** One cell session's run stamp as the e2e asserts on it. */
interface StampLine {
  readonly sessionId: string
  readonly group?: string
  readonly district?: string
  readonly environmentId: string
  readonly repetition: number
}

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('shift-driver requires a config path')

/** Every shift ledger and every grouped run stamp in the persistence root. */
async function readRoot(persistence: SessionPersistence): Promise<{ ledgers: LedgerLine[]; stamps: StampLine[] }> {
  const ledgers: LedgerLine[] = []
  const stamps: StampLine[] = []
  for (const stored of await persistence.list()) {
    const { events } = await persistence.inspect(stored.id)
    const shiftEvents = events.filter((event: SessionEvent) => event.type.startsWith('shift/'))
    if (shiftEvents.length > 0) {
      ledgers.push({ sessionId: stored.id, events: shiftEvents.map(event => ({ type: event.type, data: event.data })) })
    }
    for (const event of events) {
      if (event.type !== 'environment/run') continue
      stamps.push({
        sessionId: stored.id,
        ...event.data.group === undefined ? {} : { group: event.data.group },
        ...event.data.district === undefined ? {} : { district: event.data.district },
        environmentId: event.data.environmentId,
        repetition: event.data.repetition,
      })
    }
  }
  return { ledgers, stamps }
}

const ctx = await boot('shift-driver-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; a slot freezes its plan against the
  // environment registry, so the driver drives only the settled application.
  await ctx.get('loader')?.await()
  const shifts = ctx.get('shifts')
  const persistence = ctx.get('sessionPersistence')
  if (shifts === undefined || persistence === undefined) throw new Error('shift-driver requires the shifts and session persistence services')
  if (process.env.DSH_TEST_SHIFT_KILL_AFTER_CELL === '1') {
    // Registered before the shift's own observer, so the process dies before
    // the ledger records the cell whose session is already durable.
    ctx.on('fleet/cell', () => {
      process.exit(KILLED)
    })
    await shifts.start()
    // An unattended driver stays up on its cadence; the kill switch ends it.
    await new Promise<never>(() => {})
  }
  await shifts.start()
  const observed = await readRoot(persistence)
  process.stdout.write(`${JSON.stringify({ type: 'result', ...observed })}\n`)
} finally {
  await ctx.fiber.dispose()
}

/**
 * Keyless REAL-composition coverage for the durable shift loop: three boots of
 * one `cordis.yml` over one persistence root. The first runs a district's slot
 * to completion; the second opens a fresh slot and dies on its first announced
 * cell; the third resumes that shift, records the orphan, runs only the cell
 * that never started, and closes the ledger.
 */

import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, describe, expect, it } from 'vitest'
import { LOADER_SMOKE_TEST_TIMEOUT_MS, runLoaderSmoke } from '@deepseek-ai/dsh-loader-smoke'
import type { ShiftEnd, ShiftResume, ShiftStart } from '@deepseek-ai/dsh-shifts'

const binScript = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/shift-driver/driver.ts', import.meta.url))
const configPath = fileURLToPath(new URL('../../../../examples/headless-agent/tests/fixtures/shift-driver/cordis.yml', import.meta.url))
const repoTsconfig = fileURLToPath(new URL('../../../../tsconfig.json', import.meta.url))

/** Three boots, each a full mock-model shift, need more than the default window. */
const PHASE_TIMEOUT_MS = 120_000
const KILLED = 9
const NIGHT_SHIFT = 'nightshift'

interface LedgerLine {
  sessionId: string
  events: { type: string; data: unknown }[]
}

interface StampLine {
  sessionId: string
  group?: string
  district?: string
  environmentId: string
  repetition: number
}

interface DriverResult {
  type: string
  ledgers: LedgerLine[]
  stamps: StampLine[]
}

const roots: string[] = []

afterAll(async () => {
  await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true })))
})

/** Boot the driver once over the shared persistence root. */
async function phase(root: string, env: Record<string, string>, expectedExitCode = 0): Promise<string> {
  const { stdout, stderr } = await runLoaderSmoke({
    label: `shift-driver (${JSON.stringify(env)})`,
    tempDirPrefix: 'shift-driver-e2e-',
    binScript,
    libBinScript: binScript,
    configPath,
    binArgs: [configPath],
    tsconfigPath: repoTsconfig,
    processTimeoutMs: PHASE_TIMEOUT_MS,
    expectedExitCode,
    env: { DSH_TEST_SESSION_ROOT: root, ...env },
  })
  expect(stderr).toBe('')
  return stdout
}

/** The last JSON line the driver printed. */
function result(stdout: string): DriverResult {
  const parsed = JSON.parse(stdout.trimEnd().split('\n').at(-1) ?? '') as DriverResult
  expect(parsed.type).toBe('result')
  return parsed
}

describe('the shift driver through a real cordis.yml, killed and restarted', () => {
  it('runs a slot, resumes the shift a kill interrupted, and never runs a recorded cell twice', async () => {
    const root = await mkdtemp(join(tmpdir(), 'shift-driver-sessions-'))
    roots.push(root)

    const first = result(await phase(root, {}))
    expect(first.ledgers).toHaveLength(1)
    const workshop = first.ledgers[0] as LedgerLine
    expect(workshop.events.map(event => event.type)).toEqual(['shift/start', 'shift/cell', 'shift/cell', 'shift/end'])
    const opened = workshop.events[0]?.data as ShiftStart
    expect(opened.shiftId).toBe(workshop.sessionId)
    expect(opened.plan).toMatchObject({
      district: 'workshop',
      environments: ['smoke:round-trip', 'smoke:unsatisfiable'],
      repetitions: 1,
    })
    expect(workshop.events.at(-1)?.data).toMatchObject({
      shiftId: workshop.sessionId,
      outcome: 'completed',
      cells: { reported: 2, error: 0, interrupted: 0 },
    })
    expect((workshop.events.at(-1)?.data as ShiftEnd).spend).toBeGreaterThan(0)
    expect(first.stamps.map(stamp => [stamp.environmentId, stamp.group, stamp.district])).toEqual([
      ['smoke:round-trip', workshop.sessionId, 'workshop'],
      ['smoke:unsatisfiable', workshop.sessionId, 'workshop'],
    ])

    // The second boot opens a fresh slot of its own district and dies on the
    // first announced cell, before the ledger records it.
    await phase(root, { DSH_TEST_SHIFT_DISTRICT: NIGHT_SHIFT, DSH_TEST_SHIFT_KILL_AFTER_CELL: '1' }, KILLED)

    const third = result(await phase(root, { DSH_TEST_SHIFT_DISTRICT: NIGHT_SHIFT }))
    const night = third.ledgers.find(ledger => ledger.sessionId !== workshop.sessionId) as LedgerLine
    expect(third.ledgers).toHaveLength(2)
    expect(night.events.map(event => event.type)).toEqual([
      'shift/start', 'shift/cell', 'shift/resume', 'shift/cell', 'shift/end',
    ])
    // The resumed shift keeps the identity the killed process froze.
    expect((night.events[0]?.data as ShiftStart).shiftId).toBe(night.sessionId)
    expect((night.events[0]?.data as ShiftStart).plan.district).toBe(NIGHT_SHIFT)

    const orphan = night.events[1]?.data as { cell: { environmentId?: string; environment: string }; outcome: { kind: string }; sessionId: string }
    expect(orphan.outcome).toEqual({ kind: 'interrupted' })
    expect(orphan.cell.environment).toBe('smoke:round-trip')
    const resumed = night.events[2]?.data as ShiftResume
    expect(resumed.done.map(cell => cell.environment)).toEqual(['smoke:round-trip'])
    expect(resumed.pending.map(cell => cell.environment)).toEqual(['smoke:unsatisfiable'])
    expect(night.events[3]?.data).toMatchObject({
      shiftId: night.sessionId,
      cell: { environment: 'smoke:unsatisfiable', repetition: 0 },
      outcome: { kind: 'reported' },
    })
    expect(night.events.at(-1)?.data).toMatchObject({
      outcome: 'completed',
      cells: { reported: 1, error: 0, interrupted: 1 },
    })

    // Every cell of the night shift has exactly one session, and the orphan's
    // is the one the killed process created.
    const nightStamps = third.stamps.filter(stamp => stamp.group === night.sessionId)
    expect(nightStamps.map(stamp => [stamp.environmentId, stamp.repetition, stamp.district])).toEqual([
      ['smoke:round-trip', 0, NIGHT_SHIFT],
      ['smoke:unsatisfiable', 0, NIGHT_SHIFT],
    ])
    expect(orphan.sessionId).toBe(nightStamps[0]?.sessionId)
    // The workshop district was not configured for the later boots, so its
    // completed shift is untouched and no second slot of it exists.
    expect(third.stamps.filter(stamp => stamp.district === 'workshop')).toHaveLength(2)
  }, PHASE_TIMEOUT_MS * 3 + LOADER_SMOKE_TEST_TIMEOUT_MS)
})

